import csv
from typing import List, Dict

def read_csv_rows(filepath: str) -> List[Dict[str, str]]:
    with open(filepath, 'r', newline='') as f:
        return list(csv.DictReader(f))

def filter_positive(rows: List[Dict[str, str]]) -> List[str]:
    return [row['name'] for row in rows if int(row['value']) > 0]

def process(filepath: str) -> List[str]:
    rows = read_csv_rows(filepath)
    return filter_positive(rows)

if __name__ == '__main__':
    print(process('data.csv'))

