import csv

def read_csv_to_dict_list(filename):
    result = []
    with open(filename, mode='r') as file:
        reader = csv.reader(file)
        headers = next(reader)
        for row in reader:
            # convert row to dictionary
            record = {}
            for i in range(len(headers)):
                record[headers[i]] = row[i]
            result.append(record)
    return result

if __name__ == '__main__':
    data = read_csv_to_dict_list('data.csv')
    print(data)

import csv

def clean_csv(filename):
    cleaned = []
    with open(filename, mode='r') as file:
        reader = csv.DictReader(file)
        for row in reader:
            if not row:
                continue
            # validate and convert
            try:
                row['age'] = int(row['age'])
            except ValueError:
                row['age'] = 0
            try:
                row['salary'] = float(row['salary'])
            except ValueError:
                row['salary'] = 0.0
            cleaned.append(row)
    return cleaned

if __name__ == '__main__':
    result = clean_csv('bad_data.csv')
    print(result)

