import csv
import unittest
import os

def load_csv(path):
    with open(path, mode='r', newline='') as f:
        reader = csv.DictReader(f)
        return [dict(row) for row in reader]

def save_csv(data, path):
    if not data:
        return
    fieldnames = list(data[0].keys())
    with open(path, mode='w', newline='') as f:
        writer = csv.DictWriter(f, fieldnames=fieldnames)
        writer.writeheader()
        writer.writerows(data)

def merge_csvs(paths, output_path):
    merged = []
    for p in paths:
        if os.path.exists(p):
            merged.extend(load_csv(p))
    save_csv(merged, output_path)

class TestCSVUtil(unittest.TestCase):
    def setUp(self):
        self.tmp = 'temp_test.csv'
        self.sample = [{'name': 'A', 'value': 10}]
        save_csv(self.sample, self.tmp)

    def tearDown(self):
        if os.path.exists(self.tmp):
            os.remove(self.tmp)

    def test_load_save(self):
        loaded = load_csv(self.tmp)
        self.assertEqual(loaded, self.sample)

    def test_merge_csvs(self):
        second = [{'name': 'B', 'value': 20}]
        save_csv(second, self.tmp)
        merge_csvs([self.tmp, self.tmp], 'merged.csv')
        merged = load_csv('merged.csv')
        self.assertEqual(len(merged), 2)
        self.assertEqual(merged[0], {'name': 'A', 'value': 10})
        self.assertEqual(merged[1], {'name': 'B', 'value': 20})

if __name__ == '__main__':
    unittest.main()
